import React from 'react';
import { useDrag } from 'react-dnd';

const TaskCard = ({ task, onEditTask }) => {
  const [{ isDragging }, drag] = useDrag(() => ({
    type: 'TASK',
    item: task,
    collect: (monitor) => ({
      isDragging: monitor.isDragging(),
    }),
  }));

  return (
    <div ref={drag} className={`task-card ${isDragging ? 'dragging' : ''}`}>
      <h4>{task.title}</h4>
      <p>{task.description}</p>
      <div className="screenshots">
        {task.screenshots.map((screenshot, index) => (
          <img
            key={index}
            src={`http://localhost:3001/screenshots/${screenshot}`}
            alt={`Screenshot ${index + 1}`}
            className="screenshot-thumbnail"
          />
        ))}
      </div>
      <button className="btn-secondary" onClick={() => onEditTask(task)}>
        Edit
      </button>
    </div>
  );
};

export default TaskCard;
